'use client'
import { cn } from '@gentleduck/libs/cn'
import { Slot, Slottable } from '@gentleduck/primitives/slot'
import { Loader } from 'lucide-react'
import * as React from 'react'
import { buttonVariants } from './button.constants'
import type { AnimationIconProps, ButtonProps } from './button.types'

/** A link cannot be disabled, so its click is stopped before anyone hears it. Enter on a link is a click too. */
export function stopClick(event: React.MouseEvent) {
  event.preventDefault()
  event.stopPropagation()
}

/** Slot lets its child's own props win, and runs the child's handler first, so the child itself is told it is held. */
export function holdChild(children: React.ReactNode, loading: boolean) {
  if (!React.isValidElement<React.HTMLAttributes<HTMLElement>>(children)) return children
  return React.cloneElement(children, {
    'aria-disabled': true,
    onClickCapture: stopClick,
    ...(loading ? { 'aria-busy': true } : {}),
  })
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      children,
      variant = 'default',
      size = 'default',
      border = 'default',
      asChild,
      className,
      loading,
      isCollapsed,
      icon,
      secondIcon,
      type = 'button',
      disabled,
      ...props
    },
    ref,
  ) => {
    const buttonClass = cn(
      buttonVariants({
        border,
        className,
        size: isCollapsed ? 'icon' : size,
        variant,
      }),
    )

    if (asChild) {
      const isDisabled = Boolean(loading) || Boolean(disabled)
      return (
        <Slot
          data-slot="button"
          {...props}
          aria-busy={loading ? true : undefined}
          aria-disabled={isDisabled ? true : props['aria-disabled']}
          className={buttonClass}
          onClickCapture={isDisabled ? stopClick : props.onClickCapture}
          ref={ref}>
          {isDisabled ? holdChild(children, Boolean(loading)) : children}
        </Slot>
      )
    }

    return (
      <button
        data-slot="button"
        {...props}
        aria-busy={loading ? true : undefined}
        className={buttonClass}
        disabled={Boolean(loading) || disabled}
        ref={ref}
        type={type}>
        {loading ? <Loader aria-hidden="true" className="animate-spin motion-reduce:animate-none" /> : icon}
        <Slottable>{!isCollapsed && children}</Slottable>
        {!isCollapsed && secondIcon && secondIcon}
      </button>
    )
  },
)
Button.displayName = 'Button'

function AnimationIcon({ children, animationIcon }: AnimationIconProps): React.JSX.Element {
  return (
    <>
      {animationIcon?.icon && animationIcon.iconPlacement === 'left' && (
        <div className="w-0 pe-0 opacity-0 transition-[width,padding,opacity,translate] duration-200 ease-(--gentleduck-motion-ease) group-hover:w-5 group-hover:pe-2 group-hover:opacity-100 ltr:translate-x-[-1.3em] ltr:group-hover:-translate-x-1 rtl:translate-x-[1.3em] rtl:group-hover:translate-x-1">
          {animationIcon?.icon}
        </div>
      )}
      {children}
      {animationIcon?.icon && animationIcon.iconPlacement === 'right' && (
        <div className="w-0 ps-0 opacity-0 transition-[width,padding,opacity,translate] duration-200 ease-(--gentleduck-motion-ease) group-hover:w-5 group-hover:translate-x-0 group-hover:ps-2 group-hover:opacity-100 ltr:translate-x-[1.3em] rtl:translate-x-[-1.3em]">
          {animationIcon?.icon}
        </div>
      )}
    </>
  )
}
AnimationIcon.displayName = 'AnimationIcon'

export { AnimationIcon, Button }

import type { Variants } from '@gentleduck/variants'
import type { buttonVariants } from './button.constants'

/**
 * Props for the Button component, combining native button attributes, variant styles, and custom options.
 */
export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    Variants.VariantProps<typeof buttonVariants> {
  /** Render as child component using Slot (e.g., for custom wrappers) */
  asChild?: boolean
  /** Controls collapsed state for buttons like sidebar toggles */
  isCollapsed?: boolean
  /** Shows loading state/spinner in the button */
  loading?: boolean
  /** Primary icon to display in the button */
  icon?: React.ReactNode
  /** Secondary icon (e.g., for split actions or toggles) */
  secondIcon?: React.ReactNode
}

/**
 * Props for components that support optional animated icons.
 */
export type AnimationIconProps = {
  /** The content inside the icon wrapper */
  children: React.ReactNode
  /**
   * Optional animated icon configuration.
   * Modify the variant to use animation styles.
   */
  animationIcon?: {
    /** Icon to animate (if applicable) */
    icon?: React.ReactNode
    /** Determines icon position relative to the children */
    iconPlacement?: 'left' | 'right'
  }
}

'use client'

import { cn } from '@gentleduck/libs/cn'
import { loadDomAnimation } from '@gentleduck/motion/motion-features'
import { useMotionPreset } from '@gentleduck/motion/motion-presets'
import { contentTransition, spinIn, tapScale } from '@gentleduck/motion/presets/content'
import { scaleIn } from '@gentleduck/motion/presets/scale-in'
import { springBouncy } from '@gentleduck/motion/transitions/springs'
import { Slot } from '@gentleduck/primitives/slot'
import { Loader } from 'lucide-react'
import { AnimatePresence, LazyMotion, m } from 'motion/react'
import * as React from 'react'
import { holdChild, stopClick } from './button'
import { buttonVariants } from './button.constants'
import type { ButtonProps } from './button.types'

const TAP_PRESET = { tap: true, transition: springBouncy }

const MotionButton = React.forwardRef<
  HTMLButtonElement,
  Omit<ButtonProps, 'onDrag' | 'onDragStart' | 'onDragEnd' | 'onAnimationStart'>
>(
  (
    {
      children,
      variant = 'default',
      size = 'default',
      border = 'default',
      asChild,
      className,
      loading,
      isCollapsed,
      icon,
      secondIcon,
      type = 'button',
      disabled,
      ...props
    },
    ref,
  ) => {
    const content = useMotionPreset(scaleIn, TAP_PRESET)
    const isDisabled = Boolean(loading) || Boolean(disabled)
    const animateState = isDisabled
      ? { ...(content.animate as Record<string, unknown>), opacity: 0.5 }
      : content.animate

    if (asChild) {
      return (
        <LazyMotion features={loadDomAnimation}>
          <m.span
            data-slot="button"
            initial={content.initial}
            animate={content.animate}
            whileTap={isDisabled ? undefined : tapScale}
            transition={content.transition}
            className={cn('inline-flex', isDisabled && 'cursor-not-allowed [&>*]:pointer-events-none')}
            // The child takes no pointer while disabled, so a click lands here.
            onClickCapture={isDisabled ? stopClick : undefined}>
            <Slot
              {...(props as React.HTMLAttributes<HTMLElement>)}
              aria-busy={loading ? true : undefined}
              aria-disabled={isDisabled ? true : props['aria-disabled']}
              className={cn(buttonVariants({ border, className, size: isCollapsed ? 'icon' : size, variant }))}
              onClickCapture={isDisabled ? stopClick : props.onClickCapture}
              ref={ref as React.Ref<HTMLElement>}>
              {isDisabled ? holdChild(children, Boolean(loading)) : children}
            </Slot>
          </m.span>
        </LazyMotion>
      )
    }

    return (
      <LazyMotion features={loadDomAnimation}>
        <m.button
          data-slot="button"
          initial={content.initial}
          animate={animateState}
          whileTap={isDisabled ? undefined : tapScale}
          transition={content.transition}
          {...props}
          aria-busy={loading ? true : undefined}
          aria-disabled={isDisabled || undefined}
          className={cn(
            buttonVariants({ border, className, size: isCollapsed ? 'icon' : size, variant }),
            'overflow-hidden',
            isDisabled && 'cursor-not-allowed',
          )}
          disabled={isDisabled}
          ref={ref}
          type={type as 'button' | 'submit' | 'reset'}>
          <AnimatePresence mode="wait" initial={false}>
            {loading ? (
              <m.span key="loader" {...spinIn} transition={contentTransition} className="inline-flex">
                <Loader aria-hidden="true" className="animate-spin motion-reduce:animate-none" />
              </m.span>
            ) : icon ? (
              <m.span key="icon" {...spinIn} transition={contentTransition} className="inline-flex">
                {icon}
              </m.span>
            ) : null}
          </AnimatePresence>
          {!isCollapsed && children && children}
          {!isCollapsed && secondIcon && secondIcon}
        </m.button>
      </LazyMotion>
    )
  },
)
MotionButton.displayName = 'MotionButton'

export { MotionButton }
